      "help": "Ordne jede Anforderung dem Bereich zu, zu dem sie am deutlichsten gehört: Aussehen, Handeln, Körperausdruck, Reden oder Wissen.",
      "short_explanation": "Eine sichere Ausdrucksweise gehört zur Sprache, ein gepflegtes Äußeres zum Erscheinungsbild und Hilfsbereitschaft zum Verhalten. Blickkontakt ist Teil der Körpersprache, eine gute Beratung setzt Fachwissen voraus.",
      "detailed_explanation": "Anforderungen an das Verkaufspersonal:\n- **Erscheinungsbild:** gepflegtes Äußeres, angemessene Kleidung.\n- **Verhalten:** Hilfsbereitschaft, Freundlichkeit, Zuverlässigkeit.\n- **Körpersprache:** Blickkontakt, offene Haltung, freundliche Mimik.\n- **Sprache:** sichere, verständliche Ausdrucksweise, höflicher Ton.\n- **Fachwissen:** kompetente Beratung zur Ware.\n\nJedes Merkmal wird genau einmal verwendet.",
