      "revision": 2,
      "area": "verkauf",
      "subtopic": "beratung",
      "variant_group": "verkauf.beratung",
      "title": "Kundenorientiertes Verhalten",
      "stem": "Im Sinne der Kundenzufriedenheit versuchen Sie sich als Verkäufer/-in in die Wünsche und Interessen Ihrer Kunden hineinzudenken. Wie verhalten Sie sich kundenorientiert?",
      "response": {
        "type": "single_choice",
        "choices": [
          {
            "id": "choice-1",
            "text": "In einem Geschäft mit Vorwahlsystem sprechen Sie den Kunden sofort nach Betreten des Geschäftes an."
          },
          {
            "id": "choice-2",
            "text": "Senioren weisen Sie zuallererst auf die Sonderangebote hin, da deren Renteneinkommen meist gering sind."
          },
          {
            "id": "choice-3",
            "text": "Die Funktionsweise eines Navigationsgerätes erklären Sie mit vielen technischen Begriffen, um den Kunden von Ihrem Fachwissen zu überzeugen."
          },
          {
            "id": "choice-4",
            "text": "Sie legen dem Kunden nur eine begrenzte Anzahl von Ware vor, um ihm die Entscheidung zu erleichtern."
          },
          {
            "id": "choice-5",
            "text": "Kundeneinwänden zur Ware widersprechen Sie freundlich und bestimmt mit dem Hinweis, dass dieser Artikel qualitativ hochwertig ist und sehr häufig gekauft wird."
          }
        ]
      },
      "solution": {
        "choice_ids": [
          "choice-4"
        ]
      },
      "materials": [],
      "requires": [],
      "help": "Kundenorientiert ist, was dem Kunden hilft – nicht, was dem Verkäufer oder der Verkäuferin nützt.",
      "short_explanation": "Wer nur eine begrenzte Auswahl vorlegt, erleichtert dem Kunden den Vergleich und die Entscheidung. Das ist kundenorientiert.",
      "detailed_explanation": "Eine gute Warenvorlage umfasst meist zwei bis drei passende Artikel. Zu viele Artikel überfordern und verzögern die Entscheidung.\n\nDie übrigen Verhaltensweisen gehen am Kunden vorbei:\n- Beim Vorwahlsystem suchen Kunden zunächst selbst aus. Sofort angesprochen zu werden, empfinden viele als aufdringlich.\n- Senioren pauschal auf Sonderangebote hinzuweisen, unterstellt ihnen wenig Geld.\n- Viele Fachbegriffe beeindrucken nicht, sondern überfordern.\n- Einwänden direkt zu widersprechen, nimmt den Kunden nicht ernst.",
      "error_paths": [
        {
          "id": "aufdringlich",
          "choice_ids": [
            "choice-1"
          ],
          "text": "Beim Vorwahlsystem wählen Kunden zunächst selbst aus. Sofort angesprochen zu werden, wirkt auf viele aufdringlich."
        },
        {
          "id": "vorurteil",
          "choice_ids": [
            "choice-2"
          ],
          "text": "Senioren pauschal geringes Einkommen zu unterstellen, ist ein Vorurteil. Kundenorientiert ist, den Bedarf zu erfragen."
        },
        {
          "id": "fachchinesisch",
          "choice_ids": [
            "choice-3"
          ],
          "text": "Viele technische Begriffe überfordern den Kunden. Kundenorientierte Erklärungen sind verständlich."
        },
        {
          "id": "widerspruch",
          "choice_ids": [
            "choice-5"
          ],
          "text": "Einwänden direkt zu widersprechen, nimmt den Kunden nicht ernst. Besser ist es, den Einwand aufzugreifen und zu klären."
        }
      ],
