      "requires": [],
      "help": "Bei der Bedarfsermittlung werden die Wünsche erfragt, bevor Ware gezeigt wird. Welche Fragen sind offen und liefern verwertbare Informationen?",
      "short_explanation": "Die Fragen nach der Wohnungseinrichtung und nach der Größe klären, welches Bild zu den Eltern passt. Es sind offene Fragen, die die nötigen Informationen für eine gezielte Auswahl liefern.",
      "detailed_explanation": "Gute Fragen zur Bedarfsermittlung sind offen und beziehen sich auf den Verwendungszweck: Wo soll das Bild hängen? Wie groß darf es sein? Welcher Stil gefällt?\n\nWeniger geeignet sind:\n- die Frage nach der Preisklasse gleich zu Beginn – sie wirkt schnell unangenehm und rückt den Preis vor den Nutzen,\n- die Frage nach der Meinung zu einem bestimmten Bild – damit wird schon Ware gezeigt, bevor der Bedarf klar ist,\n- geschlossene Fragen wie „Haben Sie sich schon …?“ oder „Soll es ein Ölbild sein?“, die nur Ja oder Nein zulassen.",
