      "help": "Welche Antwort hilft dem Kunden, die Ware zu verstehen?",
      "short_explanation": "Fachbegriffe gehören zur fachkundigen Beratung, müssen aber erklärt werden. Eine verständliche Erklärung macht dem Kunden deutlich, was die Begriffe für ihn bedeuten.",
      "detailed_explanation": "Sprache im Verkaufsgespräch:\n- deutlich und in angemessener Lautstärke sprechen,\n- Fachbegriffe verwenden und in verständliche Worte übersetzen,\n- den Kunden zu Wort kommen lassen und zuhören,\n- nicht zu viel und nicht zu wenig reden.\n\nWer zu laut oder zu leise spricht, ständig redet oder schweigt, erschwert das Gespräch und verfehlt die Bedürfnisse des Kunden.",
