      "materials": [],
      "requires": [],
      "help": "Der Kunde ist noch vor Geschäftsschluss gekommen und hat ein konkretes Anliegen. Welche Reaktion berücksichtigt sein Anliegen?",
      "short_explanation": "Wer vor Geschäftsschluss kommt, wird genauso freundlich und vollständig beraten wie jeder andere Kunde. Zeitdruck oder Abwimmeln verärgern ihn und kosten Umsatz und Vertrauen.",
      "detailed_explanation": "Kurz vor Ladenschluss gilt:\n- Kunden, die sich noch im Geschäft befinden, werden bedient und beraten.\n- Der Kunde soll nicht spüren, dass die Zeit knapp ist; Hektik wirkt unfreundlich.\n- Ein Hinweis auf den Geschäftsschluss oder die Bitte, morgen wiederzukommen, wirkt abweisend.\n\nEine Reservierung kann eine Serviceleistung sein, wenn der Kunde sie wünscht. Als Ersatz für die Beratung ist sie nicht geeignet.",
