      "area": "verkauf",
      "subtopic": "service",
      "variant_group": "verkauf.service",
      "title": "Beratung bei Selbstbedienung",
      "stem": "Sie sind zurzeit in der Lebensmittelabteilung, die in Selbstbedienung geführt wird, eingesetzt. Eine Kundin möchte für eine Familienfeier den passenden Wein kaufen und bittet Sie um eine Beratung. Wie verhalten Sie sich kundenorientiert?",
