      "help": "Zahlungsbezogen ist ein Service, der dem Kunden das Bezahlen erleichtert.",
      "short_explanation": "Die Möglichkeit zur Ratenzahlung erleichtert dem Kunden das Bezahlen. Sie ist deshalb eine zahlungsbezogene Serviceleistung.",
      "detailed_explanation": "Serviceleistungen lassen sich einteilen:\n- **zahlungsbezogen:** Ratenzahlung, Kartenzahlung, Kauf auf Rechnung, Kundenkarte,\n- **warenbezogen:** sicheres Verpacken, Auswahlsendung zur Ansicht, Reparaturen, Montage, Einstellen der Skibindung,\n- **kundenbezogen:** Parkplätze, Kinderbetreuung, Toiletten, Kundenzeitschrift.\n\nEinwickeln, Auswahl zur Ansicht, Reparatur und Einstellen der Bindung betreffen die Ware, nicht die Bezahlung.",
