      "requires": [],
      "help": "Jede Aussage einzeln an genau einer Zeile der Tabelle prüfen. Maßgeblich sind die Spalten „Vorjahr“ und „Aktuelles Jahr“: Ist der Wert im aktuellen Jahr größer, hat er zugenommen.",
      "short_explanation": "Richtig sind zwei Aussagen: Im Vorjahr gab es mehr meldepflichtige Wegeunfälle (223.973 gegenüber 188.452), und die tödlichen Wegeunfälle haben zugenommen (von 367 auf 394).",
      "detailed_explanation": "Vorgehen beim Auswerten einer Statistik:\n- Zuerst die Überschriften der Zeilen und Spalten lesen.\n- Für jede Aussage die passende Zeile suchen.\n- Vorjahr und aktuelles Jahr vergleichen. Das Vorzeichen in der Spalte „Veränderung in %“ zeigt, ob ein Wert gestiegen (+) oder gesunken (−) ist.\n\nIn dieser Statistik sind alle meldepflichtigen Unfälle zurückgegangen. Bei den tödlichen Unfällen sind nur die Wegeunfälle gestiegen, und zwar um 27. Die tödlichen Arbeitsunfälle sind um 21 gesunken. Deshalb haben die tödlichen Unfälle insgesamt leicht zugenommen, nämlich um 6.",
