      "help": "Bei jeder Angabe unterscheiden: Beschreibt sie den Artikel oder den Lieferer?",
      "short_explanation": "Artikelbezeichnung, GTIN und Bruttoverkaufspreis beschreiben den Artikel und gehören zu den Artikelstammdaten. Adresse und Lieferernummer beschreiben den Lieferer und gehören zu den Liefererstammdaten.",
      "detailed_explanation": "Ein Warenwirtschaftssystem trennt verschiedene Stammdateien:\n- **Artikelstammdaten:** Artikelnummer, Artikelbezeichnung, GTIN, Warengruppe, Einkaufs- und Verkaufspreis, Melde- und Mindestbestand.\n- **Liefererstammdaten:** Lieferernummer, Name und Adresse, Ansprechpartner, Liefer- und Zahlungsbedingungen.\n\nStammdaten ändern sich selten. Davon zu unterscheiden sind **Bewegungsdaten** wie Wareneingänge und Verkäufe, die laufend neu entstehen.",
