      "materials": [],
      "requires": [],
      "help": "Das System glaubt, es seien 160 Pakete vorhanden. Tatsächlich sind es nur 80. Was passiert beim Nachbestellen?",
      "short_explanation": "Weil das System 80 Pakete zu viel annimmt, meldet es den Meldebestand zu spät. Die Nachbestellung kommt verspätet, und der Artikel kann ausgehen – es kann zu Verkaufsstockungen kommen.",
      "detailed_explanation": "Ein zu hoher Soll-Bestand ist tückisch: Das Warenwirtschaftssystem erkennt ihn nicht. Es rechnet weiter mit 160 Paketen und löst die Bestellung erst aus, wenn der gebuchte Bestand den Meldebestand erreicht. In Wirklichkeit ist dann längst weniger Ware vorhanden.\n\nDeshalb muss der Soll-Bestand nach der Inventur auf den Ist-Bestand berichtigt werden. Automatisch korrigiert das System weder den Bestand noch die Bestellmenge.",
