      "requires": [],
      "help": "Laut Artikeldatei liegt der Soll-Bestand bei 160 Paketen, gezählt wurden 80. Welche Antwort erklärt genau 80 Pakete zu viel im System?",
      "short_explanation": "Im System stehen 160 Pakete, tatsächlich vorhanden sind 80. Wurde die Lieferung von 80 Paketen am 09.10. doppelt erfasst, stehen genau 80 Pakete zu viel im System. Das erklärt die Differenz.",
      "detailed_explanation": "Prüfe jede Erklärung daraufhin, ob sie einen um 80 Pakete zu hohen Soll-Bestand verursacht:\n- **Lieferung doppelt erfasst:** 80 Pakete zu viel gebucht – passt genau.\n- **Zugang als Abgang gebucht:** Der Soll-Bestand wäre zu niedrig, nicht zu hoch.\n- **Zugang nicht erfasst:** Auch dann wäre der Soll-Bestand zu niedrig.\n- **Mehrlieferung erfasst:** Wurde sie richtig gebucht, stimmen Soll und Ist überein.\n- **Zu viel gezählt:** Dann wäre der Ist-Bestand höher, nicht niedriger.\n\nDie Artikeldatei weist am 09.10. einen Zugang von 160 Paketen aus. Das entspricht einer doppelt gebuchten Lieferung von 80 Paketen.",
