      "title": "Bestellpunktverfahren",
      "stem": "Das Warenhaus Maxikauf GmbH arbeitet mit einem geschlossenen Warenwirtschaftssystem (WWS). Es ermöglicht bei vielen Artikeln die Bestellung nach dem Bestellpunktverfahren. Welchen Vorteil bringt diese Art der Bestellung für das Warenhaus?",
