      "requires": [],
      "help": "Meldebestand = Mindestbestand + täglicher Absatz × Lieferzeit. Was ändert sich, wenn die Lieferzeit um 2 Tage steigt?",
      "short_explanation": "Bei 8 verkauften Fitnessbändern pro Tag werden in 2 zusätzlichen Liefertagen 16 Bänder mehr verkauft. Damit die Ware bis zur Lieferung reicht, muss früher bestellt werden – der Meldebestand steigt von 40 auf 56, also um 16 Stück.",
      "detailed_explanation": "Rechnung mit den Lagerdaten:\n- bisher: 16 + 8 × 3 = 40 Stück Meldebestand\n- neu: 16 + 8 × 5 = 56 Stück Meldebestand\n- Unterschied: 56 − 40 = 16 Stück\n\nDer Mindestbestand ist die Reserve für Unvorhergesehenes. Die längere Lieferzeit ist bekannt und wird über den Meldebestand berücksichtigt. Den Lieferer zu wechseln oder zu kündigen, sichert die Verkaufsbereitschaft nicht sofort. Die Lagerdauer ist eine Kennzahl, die sich aus den Verkäufen ergibt, und keine Stellgröße.",
