      "detailed_explanation": "Die drei wichtigen Bestandsgrößen:\n- **Mindestbestand:** Sicherheitsreserve; sie soll nur im Notfall angegriffen werden.\n- **Meldebestand:** Bei diesem Bestand wird nachbestellt: Mindestbestand + Tagesabsatz × Lieferzeit.\n- **Höchstbestand:** Diese Menge soll wegen Platz und Kapitalbindung nicht überschritten werden.\n\nMit Mindestliefermengen des Lieferanten, der Regalbestückung oder der Verbundplatzierung hat der Mindestbestand nichts zu tun.",
