      "stem": "Der Preis eines Artikels wird während einer Angebotswoche um 20 % reduziert. Die Preisänderung ist im Artikelstamm gespeichert. Entscheiden Sie, welche Vorgehensweise beim Kassieren korrekt ist!\n\nSie erfassen die Ware mit dem Handscanner ...",
