      "detailed_explanation": "Bezugskalkulation:\n- Listeneinkaufspreis\n- − Liefererrabatt\n- = Zieleinkaufspreis\n- − Liefererskonto\n- = Bareinkaufspreis\n- + Bezugskosten (Fracht, Porto, Verpackung, Transportversicherung)\n- = Bezugspreis\n\nPersonal, Miete für Lagerräume, Werbung und Abfallentsorgung entstehen durch den laufenden Geschäftsbetrieb. Sie sind Handlungskosten und werden erst bei der Verkaufskalkulation berücksichtigt.",
