      "detailed_explanation": "Kalkulationsschema im Einzelhandel:\n- Bezugspreis\n- + Handlungskosten\n- = Selbstkostenpreis\n- + Gewinn\n- = Nettoverkaufspreis\n- + Umsatzsteuer\n- = Bruttoverkaufspreis\n\nDaraus folgt: Handlungskosten stecken nicht im Bezugspreis, sie enthalten weder Gewinn noch Umsatzsteuer, und ein Liefererrabatt senkt den Bezugspreis, nicht die Handlungskosten.",
