      "materials": [],
      "requires": [],
      "help": "Statt 100 kommen 500 Kartons auf einmal. Was bedeutet das für Platz, Kapital und Umschlag?",
      "short_explanation": "Wer statt der üblichen 100 plötzlich 500 Geschenkkartons annimmt, braucht fünfmal so viel Lagerplatz. Es kann passieren, dass die Lagerkapazität nicht ausreicht.",
      "detailed_explanation": "Ein günstiger Großeinkauf senkt zwar den Stückpreis, hat aber Folgen für das Lager:\n- **Platzbedarf:** Die Menge ist fünfmal so groß wie üblich – der vorhandene Lagerraum reicht womöglich nicht.\n- **Kapitalbindung:** Mehr Ware bindet mehr Geld; sie steigt, statt zu sinken.\n- **Umschlagshäufigkeit:** Der durchschnittliche Lagerbestand steigt, die Umschlagshäufigkeit sinkt.\n\nDer Mindestbestand ist eine Sicherheitsreserve gegen Lieferstörungen und ändert sich durch eine einmalige Großbestellung nicht. Einen Grund, die Annahme zu verweigern, gibt es nicht – die Menge wurde ja so bestellt.",
