      "materials": [],
      "requires": [],
      "help": "Die Hosen sind nur leicht fehlerhaft, und den Fehler hat das eigene Haus verursacht. Wie lässt sich trotzdem noch Umsatz erzielen?",
      "short_explanation": "Leicht farbabweichende Hosen sind noch verkaufsfähig, aber nicht mehr zum vollen Preis. Getrennt präsentiert und im Preis reduziert, lassen sie sich noch verkaufen – das bringt Umsatz und ist ehrlich gegenüber den Kunden.",
      "detailed_explanation": "Bei Ware mit kleinen Fehlern sind folgende Gesichtspunkte abzuwägen:\n- **Verkaufsfähigkeit:** Leichte Farbabweichungen stören den Gebrauch nicht.\n- **Ehrlichkeit:** Kunden sollen erkennen, dass die Ware nicht einwandfrei ist. Ein eigener Warenträger und ein reduzierter Preis machen das deutlich.\n- **Wirtschaftlichkeit:** Ein reduzierter Preis bringt mehr ein als Vernichten oder Verschenken.\n\nDer Lieferer kann nicht in Anspruch genommen werden, weil der Schaden durch falsche Lagerung im eigenen Haus entstanden ist. Die Hosen unverändert zum vollen Preis anzubieten, führt zu Reklamationen und Ärger.",
