      "requires": [],
      "help": "Prüfe jede Ware: Temperatur, Feuchtigkeit, Witterung und Gewicht. Wo passt alles zusammen?",
      "short_explanation": "Schwere Kartons mit Kopierpapier gehören in die unteren Regalfächer (Bückzone). Dort können sie nicht herabfallen, und das Regal bleibt standsicher.",
      "detailed_explanation": "Sachgerechte Lagerung richtet sich nach den Eigenschaften der Ware:\n- **Schwere Ware** unten lagern: Das verhindert Unfälle durch herabfallende Ware und sichert die Standfestigkeit. Beim Herausnehmen auf rückenschonendes Heben achten.\n- **Frisches Obst** wie Süßkirschen kühl, aber nicht gefroren lagern; bei −25 °C wird es beschädigt.\n- **Tiefkühlware** muss dauerhaft bei höchstens −18 °C bleiben; +12 °C unterbricht die Kühlkette.\n- **Leder** braucht trockene, luftige Räume, sonst bildet sich Schimmel.\n- **Kartons** vor Nässe und Witterung schützen.",
