      "title": "Skonto erklären",
      "stem": "Sie werden beauftragt, die Rechnung der Farben-Welt GmbH zu begleichen. Die Farben-Welt GmbH bietet die Bezahlung unter Abzug von Skonto an. Welche Erklärung zu „Skonto“ ist richtig?",
