      "materials": [],
      "requires": [],
      "help": "Skonto hängt mit dem Zeitpunkt der Zahlung zusammen, nicht mit der Menge oder der Dauer der Geschäftsbeziehung.",
      "short_explanation": "Skonto ist ein Preisnachlass für schnelles Bezahlen: Wer die Rechnung innerhalb der vereinbarten Skontofrist begleicht, darf einen festgelegten Prozentsatz abziehen.",
      "detailed_explanation": "Die wichtigsten Nachlassarten im Überblick:\n- **Skonto:** Nachlass für Zahlung innerhalb einer vereinbarten Frist, z. B. „2 % Skonto bei Zahlung innerhalb von 10 Tagen“.\n- **Mengenrabatt:** Nachlass für große Bestellmengen.\n- **Treuerabatt:** Nachlass für langjährige Kundschaft.\n- **Bonus:** nachträglich gewährter Nachlass, wenn ein vereinbarter Jahresumsatz erreicht wird.\n\nDie Skontofrist beginnt mit der Rechnung. Wann bestellt wurde, spielt dafür keine Rolle.",
