      "requires": [],
      "help": "Rechne bei jeder Antwort nach, ob die Stückzahl stimmt. Nur bei einem Mengenmangel weicht die Anzahl ab.",
      "short_explanation": "Bestellt wurden 8 × 10 = 80 Pullover, geliefert 12 × 6 = 72 Pullover. Es fehlen 8 Stück – ein Mangel in der Menge.",
      "detailed_explanation": "Beim Wareneingang werden verschiedene Abweichungen unterschieden:\n- **Mangel in der Menge:** Es wird mehr oder weniger geliefert als bestellt – hier 72 statt 80 Pullover.\n- **Mangel in der Art:** Es wird eine andere Ware geliefert, etwa V-Ausschnitt statt Rollkragen.\n- **Mangel in der Beschaffenheit (Güte):** Die Ware hat Fehler oder nicht die vereinbarte Qualität, etwa ein Webfehler oder ein zu geringer Baumwollanteil.\n- **Verspätete Lieferung:** Die Ware kommt später als vereinbart. Das ist kein Mangel der Ware, sondern eine Frage der Lieferzeit.\n\nVerpackungseinheiten beachten: Die Zahl der Kartons allein sagt nichts aus, entscheidend ist die Gesamtzahl der Stücke.",
