      "requires": [],
      "help": "Vergleiche Position für Position: Artikelnummer, Bezeichnung, Farbe, Menge und Preis. Prüfe außerdem das Lieferdatum gegen die vereinbarte Lieferzeit.",
      "short_explanation": "Bestellt wurde das Metallic-Effekt-Spray in Gold (Artikel 18501), geliefert und berechnet wurde Silber (Artikel 18500). Die gelieferte Ware weicht in der Art von der Bestellung ab. Das ist ein Mangel, der festgehalten und beim Lieferer beanstandet werden muss.",
      "detailed_explanation": "Prüfung des Wareneingangs anhand der Belege:\n- **Lieferzeit:** Bestellt am 4. November mit 2 Wochen Lieferzeit, eingetroffen am 15. November – also rechtzeitig.\n- **Versandkosten:** Laut Bestellung wird frei Haus geliefert; Versandkosten sind deshalb nicht zu berechnen.\n- **Gesamtpreise:** 150 × 6,90 € = 1.035,00 €, 100 × 5,40 € = 540,00 €, 100 × 7,20 € = 720,00 € – alle Beträge stimmen.\n- **Textil-Farben:** Die neue Artikelnummer 14959 wurde beim Messebesuch angekündigt. Bezeichnung, Menge und Preis stimmen; eine geänderte Nummer allein ist kein Mangel.\n- **Metallic-Effekt-Spray:** Gold war bestellt, Silber wurde geliefert. Hier stimmt die Ware selbst nicht.\n\n**Merksatz:** Bei der Wareneingangsprüfung zählt, ob Art, Menge und Beschaffenheit der Ware der Bestellung entsprechen.",
