      "variant_group": "wwk.wws",
      "title": "WWS-Daten für den Wareneinkauf zum Museumsfest",
      "stem": "In Frankfurt am Main findet jährlich ein Museumsfest statt. Aus diesem Anlass öffnet Ihr Warenhaus - wie im letzten Jahr - am Sonntag von 13:00 Uhr bis 18:00 Uhr. Welche Daten aus dem Warenwirtschaftssystem benötigen Sie unter anderem für den Wareneinkauf?",
      "response": {
        "type": "single_choice",
        "choices": [
          {
            "id": "choice-1",
            "text": "Die Gewinne der letzten Sonntagsöffnung"
          },
          {
            "id": "choice-2",
            "text": "Den Warenabsatz der letzten Sonntagsöffnung"
          },
          {
            "id": "choice-3",
            "text": "Die Kassendifferenz der letzten Sonntagsöffnung"
          },
          {
            "id": "choice-4",
            "text": "Die Provision pro Verkäufer/Verkäuferin am Tag der letzten Sonntagsöffnung"
          },
          {
            "id": "choice-5",
            "text": "Den durchschnittlichen Lagerbestand des letzten Jahres"
          }
        ]
      },
      "solution": {
        "choice_ids": [
          "choice-2"
        ]
      },
      "materials": [],
      "requires": [],
      "help": "Für den Einkauf ist wichtig, welche Artikel beim letzten vergleichbaren Anlass wie oft verkauft wurden.",
      "short_explanation": "Die beste Grundlage für den Einkauf ist der Warenabsatz der letzten Sonntagsöffnung: Er zeigt, welche Artikel bei diesem Anlass in welcher Menge gekauft wurden.",
      "detailed_explanation": "Für die Einkaufsplanung zählt die Menge, die voraussichtlich verkauft wird. Der Absatz der letzten vergleichbaren Sonntagsöffnung ist dafür der beste Anhaltspunkt – ergänzt um aktuelle Trends.\n\nGewinne, Kassendifferenzen und Provisionen sagen nichts darüber aus, welche Artikel gebraucht werden. Der durchschnittliche Lagerbestand eines ganzen Jahres berücksichtigt den besonderen Anlass nicht.",
      "error_paths": [
        {
          "id": "gewinn-statt-absatz",
          "choice_ids": [
            "choice-1"
          ],
          "text": "Der Gewinn zeigt den wirtschaftlichen Erfolg, aber nicht, welche Artikel in welcher Menge verkauft wurden."
        },
        {
          "id": "jahresdurchschnitt",
          "choice_ids": [
            "choice-5"
          ],
          "text": "Ein Jahresdurchschnitt blendet den besonderen Anlass aus. Für den Sonntag zählt der Absatz der letzten vergleichbaren Öffnung."
        }
      ],
