      "requires": [],
      "help": "„Renner“ und „Penner“ sind umgangssprachliche Begriffe für Artikel mit besonders hohen und besonders niedrigen Verkaufszahlen.",
      "short_explanation": "Die Renner- und Pennerliste zeigt, welche Artikel sich besonders gut (Renner) und welche sich schlecht (Penner) verkaufen. So lässt sich das Sortiment gezielt anpassen.",
      "detailed_explanation": "Die Liste wertet die Verkaufsdaten des Warenwirtschaftssystems aus:\n- **Renner:** Artikel mit hohem Absatz – hier ist auf ausreichenden Bestand und gute Platzierung zu achten.\n- **Penner (Ladenhüter):** Artikel mit geringem Absatz – sie werden eventuell reduziert, umplatziert oder aus dem Sortiment genommen.\n\nZum Mindesthaltbarkeitsdatum oder zum Zustand der Ware sagt die Liste nichts. Bestellvorschläge ergeben sich aus Bestand und Meldebestand, nicht aus dieser Liste.",
