      "requires": [],
      "help": "Umsatz entsteht durch Verkäufe. Welche Daten zeigen, was verkauft wurde?",
      "short_explanation": "Für die Umsatzentwicklung sind die Verkaufsdaten erforderlich: Welche Artikel wurden in welcher Menge und zu welchem Wert verkauft? Das Warenwirtschaftssystem liefert diese Daten artikelgenau.",
      "detailed_explanation": "Umsatz = verkaufte Menge × Verkaufspreis. Für die Auswertung der letzten drei Monate sind deshalb die artikelgenauen Verkaufsdaten nach Menge und Wert erforderlich.\n\nDie anderen Unterlagen betreffen andere Bereiche:\n- Bestellkopien, Lieferscheine und Lieferantenrechnungen dokumentieren den Einkauf.\n- Der durchschnittliche Lagerbestand dient der Berechnung von Lagerkennzahlen.\n- Die Kundenfrequenz zeigt, wie viele Kunden kamen, aber nicht, was sie gekauft haben.",
